/bin/bash -lc "mkdir -p pc1/etc/bind/lab-zones
python3 - <<'PY'
from pathlib import Path
zones = {
 'example.com': {'shop':'10.15.4.14','blog':'10.15.5.11'},
 'company.com': {'dept':'10.15.5.12','intranet':'10.15.5.13','mail':'10.15.2.13'},
 'service.com': {'api':'10.15.5.14'},
 'lab.net': {'ai.research':'10.15.6.12','data.research':'10.15.6.13','dev':'10.15.6.14'},
 'tools.net': {'ci':'10.15.7.11'},
 'university.edu': {'vpn':'10.15.7.12','courses':'10.15.7.13','mail':'10.15.3.13'},
 'campus.edu': {'portal':'10.15.7.14'},
 'unibo.it': {'studenti':'10.15.8.11'},
 'comune.it': {'servizi':'10.15.8.12'},
 'regione.it': {'dati':'10.15.8.13'},
}
config = '''// Lab-only authoritative DNS. Existing routing provides access from every LAN.
options {
    directory \"/etc/bind\";
    listen-on port 53 { 127.0.0.1; 10.15.1.11; };
    listen-on-v6 { none; };
    allow-query { any; };
    recursion no;
    pid-file \"/run/lab-named.pid\";
};
'''
for zone, hosts in zones.items():
    config += f'zone \"{zone}\" {{ type primary; file \"/etc/bind/lab-zones/{zone}\"; }};\\n'
    lines = ['"'$TTL 300'"', f'@ IN SOA ns.{zone}. hostmaster.{zone}. ( 1 3600 600 604800 300 )', f'@ IN NS ns.{zone}.', 'ns IN A 10.15.1.11']
    if zone in ('company.com', 'university.edu'):
        lines.append(f'@ IN MX 10 mail.{zone}.')
    lines.extend(f'{host} IN A {addr}' for host, addr in hosts.items())
    Path(f'pc1/etc/bind/lab-zones/{zone}').write_text('\\n'.join(lines)+'\\n')
Path('pc1/etc/bind/lab-named.conf').write_text(config)
for path in sorted(Path('.').glob('*.startup')):
    s = path.read_text()
    marker = 'set -eu\\n'
    s = s.replace(marker, marker + '# Use the lab DNS server for names across all LANs.\\nprintf \"nameserver 10.15.1.11\\\\n\" > /etc/resolv.conf\\n', 1)
    if path.name == 'pc1.startup':
        marker2 = '# Gateway ICMP warmup;'
        s = s.replace(marker2, '# Start the authoritative lab DNS service after the interface is configured.\\nnamed -c /etc/bind/lab-named.conf\\n\\n' + marker2, 1)
    path.write_text(s)
PY
command -v named-checkconf || true
command -v shellcheck || true
for f in *.startup; do sh -n \""'$f" || exit 1; done'

