/bin/bash -lc "python3 - <<'PY'
from pathlib import Path
import re
expected={'shop.example.com':16,'blog.example.com':17,'dept.company.com':18,'intranet.company.com':19,'api.service.com':20,'ai.research.lab.net':22,'data.research.lab.net':23,'dev.lab.net':24,'ci.tools.net':25,'vpn.university.edu':26,'courses.university.edu':27,'portal.campus.edu':28,'studenti.unibo.it':29,'servizi.comune.it':30,'dati.regione.it':31,'mail.company.com':7,'mail.university.edu':11}
records={}
for p in Path('pc1/etc/bind/lab-zones').iterdir():
 for line in p.read_text().splitlines():
  m=re.fullmatch(r'(\\S+) IN A (\\S+)',line)
  if m: records[m[1]+'.'+p.name]=m[2]
for name,pc in expected.items():
 s=Path(f'pc{pc}.startup').read_text()
 ip=re.search(r'inet (10\\.15\\.\\d+\\.\\d+)/24',s).group(1)
 assert records[name]==ip,(name,records.get(name),ip)
for domain in ('company.com','university.edu'):
 assert f'@ IN MX 10 mail.{domain}.' in Path('pc1/etc/bind/lab-zones',domain).read_text()
for p in Path('.').glob('*.startup'):
 assert 'nameserver 10.15.1.11' in p.read_text(),p
print(f'Validated {len(expected)} A records against PC addresses, both MX records, and all 48 resolver configurations.')
PY"

